package in.tutorlink.security; import in.tutorlink.repository.*; import org.springframework.security.authentication.*; import org.springframework.security.core.*; import org.springframework.security.core.authority.*; import org.springframework.security.core.context.*; import org.springframework.stereotype.*; import org.springframework.web.filter.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var claims=jwt.parse(h.substring(7));var u=users.findById(Long.valueOf(claims.getSubject())).orElse(null);if(u!=null){var a=List.<GrantedAuthority>of(new SimpleGrantedAuthority("ROLE_"+u.role));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.id,null,a));}}catch(Exception ignored){} c.doFilter(r,s);}}
